<div class="field"><label>Name</label><input name="name" required value="{{old('name',$product->name??'')}}"></div><div class="field"><label>Slug</label><input name="slug" value="{{old('slug',$product->slug??'')}}"></div><div class="field"><label>SKU</label><input name="sku" value="{{old('sku',$product->sku??'')}}"></div><div class="row"><div class="field" style="flex:1"><label>Price</label><input type="number" step="0.01" min="0" name="price" value="{{old('price',$product->price??'')}}"></div><div class="field" style="width:130px"><label>Currency</label><input name="currency" maxlength="3" value="{{old('currency',$product->currency??'USD')}}"></div></div><div class="field"><label>Category</label><input name="category" value="{{old('category',$product->category??'')}}"></div><div class="field"><label>Description</label><textarea name="description">{{old('description',$product->description??'')}}</textarea></div><div class="field"><label>Image URLs (one per line)</label><textarea name="image_urls">{{old('image_urls',isset($product)?implode("\n",$product->image_urls??[]):'')}}</textarea></div><div class="field"><label><input type="checkbox" name="active" value="1" {{old('active',isset($product)?$product->active:true)?'checked':''}}> Active</label></div>